using NUnit.Framework;
using UnityEngine;
public class HonorsAnchorLifecycleTests {
    ARMarkerProfile Profile()=>JsonUtility.FromJson<ARMarkerProfileRegistry.Bundle>(Resources.Load<TextAsset>("Honors/marker_profiles").text).profiles[0];
    [Test] public void CandidateSettleSnapshotAndLateArrival(){var s=new ARAnchorSessionState();Assert.IsFalse(s.Observe("A",true,0,.6));Assert.IsTrue(s.Observe("A",true,.7,.6));var p=Profile();var a=s.Begin("A",new Pose(Vector3.one,Quaternion.identity),p,.7);p.scale=2;Assert.That(a.profile.scale,Is.EqualTo(1));Assert.IsFalse(s.Observe("B",true,.8,.6));Assert.IsFalse(s.Accept(a));Assert.IsTrue(s.Observe("B",true,1.5,.6));var b=s.Begin("B",new Pose(Vector3.zero,Quaternion.identity),Profile(),1.5);Assert.IsTrue(s.Accept(b));Assert.IsTrue(s.HasValidAnchor);}
    [Test] public void FailTimeoutPauseDisableKeepPreviousAnchor(){var s=new ARAnchorSessionState();s.Observe("A",true,0,0);var a=s.Begin("A",new Pose(),Profile(),0);Assert.IsTrue(s.Accept(a));s.ForceReanchor();s.Observe("B",true,1,0);var b=s.Begin("B",new Pose(),Profile(),1);Assert.IsTrue(s.Timeout(10,8));Assert.IsFalse(s.Accept(b));Assert.IsTrue(s.HasValidAnchor);s.Suspend();Assert.That(s.State,Is.EqualTo(ARAnchorSessionState.Phase.Suspended));s.Resume();Assert.IsTrue(s.HasValidAnchor);s.Observe("A",false,11,.6);Assert.That(s.State,Is.EqualTo(ARAnchorSessionState.Phase.Limited));Assert.IsTrue(s.HasValidAnchor);}
    [Test] public void LimitedRecoveryAndUnknownTracking(){var s=new ARAnchorSessionState();s.Observe("A",true,0,0);var a=s.Begin("A",new Pose(),Profile(),0);s.Accept(a);s.MarkLimited();Assert.That(s.State,Is.EqualTo(ARAnchorSessionState.Phase.Limited));s.Observe("A",true,1,.6);Assert.That(s.State,Is.EqualTo(ARAnchorSessionState.Phase.Anchored));s.Observe("",false,2,.6);Assert.IsTrue(s.HasValidAnchor);s.AnchorLost();Assert.IsFalse(s.HasValidAnchor);}
}
